ALTER TABLE maintenance_pm_schedules ADD COLUMN calculation_policy VARCHAR(20) NOT NULL DEFAULT 'ACTUAL_BASED', ADD KEY ix_pm_policy(calculation_policy), ADD CONSTRAINT ck_pm_policy CHECK(calculation_policy IN('ACTUAL_BASED','FIXED_CYCLE'));
ALTER TABLE maintenance_pm_histories ADD COLUMN target_previous DECIMAL(14,3) NULL, ADD COLUMN target_next DECIMAL(14,3) NULL, ADD COLUMN mechanic_id INT UNSIGNED NULL, ADD COLUMN supervisor_id INT UNSIGNED NULL, ADD COLUMN unit_id INT UNSIGNED NULL, ADD COLUMN branch_id INT UNSIGNED NULL, ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'VERIFIED', ADD CONSTRAINT fk_pm_hist_mechanic FOREIGN KEY(mechanic_id) REFERENCES users(id), ADD CONSTRAINT fk_pm_hist_supervisor FOREIGN KEY(supervisor_id) REFERENCES users(id), ADD KEY ix_pm_hist_scope(branch_id,unit_id,performed_on);
